#include <bits/stdc++.h>
using namespace std;

class Modular {
public:
    int m;

    Modular(int m) : m(m) {}

    int valueOf(int x) {
        x %= m;
        if (x < 0) x += m;
        return x;
    }

    int valueOf(long long x) {
        x %= m;
        if (x < 0) x += m;
        return (int)x;
    }

    int mul(int x, int y) {
        return valueOf((long long)x * y);
    }

    int plus(int x, int y) {
        return valueOf(x + y);
    }
};

class FastInput {
private:
    istream* is;
    char buf[1 << 13];
    int bufLen;
    int bufOffset;
    int next;

    int read() {
        while (bufLen == bufOffset) {
            bufOffset = 0;
            if (!is->read(buf, sizeof(buf))) {
                bufLen = -1;
                return -1;
            }
            bufLen = is->gcount();
            if (bufLen == -1) return -1;
        }
        return buf[bufOffset++];
    }

public:
    FastInput(istream& is) : is(&is), bufLen(0), bufOffset(0), next(0) {
        next = read();
    }

    void skipBlank() {
        while (next >= 0 && next <= 32) {
            next = read();
        }
    }

    int readInt() {
        int sign = 1;
        skipBlank();
        if (next == '+' || next == '-') {
            sign = (next == '+') ? 1 : -1;
            next = read();
        }
        int val = 0;
        if (sign == 1) {
            while (next >= '0' && next <= '9') {
                val = val * 10 + (next - '0');
                next = read();
            }
        } else {
            while (next >= '0' && next <= '9') {
                val = val * 10 - (next - '0');
                next = read();
            }
        }
        return val;
    }
};

