            musics[i][1] = in.readInt();
            cnts[musics[i][1]]++;
        }

        int c1 = cnts[1];
        int c2 = cnts[2];
        int c3 = cnts[3];

        vector<vector<vector<vector<int>>>> comp(c1 + 1, vector<vector<vector<int>>>(c2 + 1, vector<vector<int>>(c3 + 1, vector<int>(4, 0))));
        for (int i = 0; i <= c1; i++) {
            for (int j = 0; j <= c2; j++) {
                for (int k = 0; k <= c3; k++) {
                    for (int t = 0; t < 4; t++) {
                        if (i == 0 && j == 0 && k == 0) {
                            comp[i][j][k][t] = 1;
                            continue;
                        }
